import re

from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class MmeFakePagingStart(GenericEPCSIMCommand):
    """Mme Fake Paging Start command class."""

    def __init__(self, connection, enbs, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Mme fake paging start command.

        :param connection: moler connection to device, terminal when command is executed.
        :param enbs: enb ids.
        :param options: options for command
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(MmeFakePagingStart, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.enbs = enbs
        self.options = options
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"mme_fake_paging_start enbs={self.enbs}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_empty_tai_list(line)
            except ParsingDone:
                pass
        return super(MmeFakePagingStart, self).on_new_line(line, is_full_line)

    # Example line: Error: eNB-2 is not configured
    _re_error = re.compile(r'(Error|ERR): (?P<ERROR>.*)')

    def _parse_error(self, line):
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group('ERROR')))
            raise ParsingDone

    # Example line: 12:56:32.422 ACR: MME-1: TAI-list is empty for eNB-1, Id=0x0000000. Fake paging will be stopped
    _re_empty_tai_list = re.compile(
        r'TAI-list is empty for eNB-(?P<ENB>\d), Id=(?P<ID>.*)\. Fake paging will be stopped')

    def _parse_empty_tai_list(self, line):
        if self._regex_helper.search(self._re_empty_tai_list, line):
            self.current_ret.setdefault("empty_tai_list", []).append({'ENB': self._regex_helper.group("ENB"),
                                                                      'ID': self._regex_helper.group("ID")})
            self.set_exception(CommandFailure(self, f"TAI-list is empty for eNB-{self._regex_helper.group('ENB')}, Id={self._regex_helper.group('ID')}. Fake paging will be stopped"))
            raise ParsingDone


